import { chromium } from "playwright";

const shots = process.env.SHOTS_DIR;
const errors = [];

const browser = await chromium.launch({ channel: "chrome", headless: true });
const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage();
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});
page.on("pageerror", (err) => errors.push(String(err)));

// 1. Dashboard
await page.goto("http://localhost:3000/", { waitUntil: "networkidle" });
await page.waitForSelector("text=Tallyo");
await page.screenshot({ path: `${shots}/01-dashboard.png`, fullPage: true });
console.log("dashboard body:", (await page.locator("body").innerText()).slice(0, 300).replace(/\n+/g, " | "));

// 2. MLS page - expand games section
await page.goto("http://localhost:3000/mls", { waitUntil: "networkidle" });
await page.click("text=MLS Games");
await page.waitForTimeout(1500);

// 3. Pick a date with completed games (May 16) from the date selector
await page.selectOption("select", { label: "Sat, May 16, 2026" });
await page.waitForSelector("text=CHI", { timeout: 15000 });
await page.screenshot({ path: `${shots}/02-mls-games.png`, fullPage: false });

// 4. Expand the MTL vs CHI game card and open scoring plays + team stats
const card = page.locator("div.cursor-pointer", { has: page.locator("text=CHI") }).first();
await card.click();
await page.waitForSelector("text=Scoring Plays", { timeout: 10000 });
await page.click("text=Scoring Plays");
await page.waitForTimeout(300);
await page.click("text=Player Stats");
await page.waitForTimeout(300);
await page.click("text=Team Stats");
await page.waitForTimeout(300);
await card.screenshot({ path: `${shots}/03-mls-card-expanded.png` });

// 5. Standings
await page.click("text=MLS Standings");
await page.waitForTimeout(800);
await page.click("text=Eastern Conference");
await page.waitForSelector("text=Points Per Game", { timeout: 10000 });
await page.screenshot({ path: `${shots}/04-mls-standings.png`, fullPage: false });

// 6. NHL standings page (wildcard grouping)
await page.goto("http://localhost:3000/nhl", { waitUntil: "networkidle" });
await page.click("text=NHL Playoff Standings");
await page.waitForTimeout(800);
await page.click("text=Western Conference");
await page.waitForSelector("text=Central Division", { timeout: 10000 });
await page.screenshot({ path: `${shots}/05-nhl-standings.png`, fullPage: false });

console.log("console errors:", errors.length ? errors : "none");
await browser.close();

